-- ── hand-written: a person's bank details ───────────────────────────────────────────────────────
-- Not SECURITY DEFINER: it runs as whoever writes the row. The person is held while their details
-- are written, and one who is not there refuses them (nothing is left for the foreign key).
CREATE FUNCTION app.check_employee_bank_account() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF current_user <> 'app_runtime' THEN
    RETURN NEW;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    NEW.created_by := app.current_user_id();
  ELSIF NEW.employee_id <> OLD.employee_id THEN
    RAISE EXCEPTION 'bank details stay with their person' USING ERRCODE = 'SE370';
  END IF;
  NEW.updated_at := clock_timestamp();
  NEW.updated_by := app.current_user_id();
  PERFORM 1 FROM public.employees e WHERE e.tenant_id = NEW.tenant_id AND e.id = NEW.employee_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such person on the payroll' USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_employee_bank_account() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER employee_bank_accounts_check BEFORE INSERT OR UPDATE ON public.employee_bank_accounts FOR EACH ROW EXECUTE FUNCTION app.check_employee_bank_account();
--> statement-breakpoint
ALTER TABLE public.employee_bank_accounts ENABLE ALWAYS TRIGGER employee_bank_accounts_check;
--> statement-breakpoint

-- ── hand-written: lending to staff, and taking it back ──────────────────────────────────────────
-- A loan or an advance is paid out of a cash or bank account by the owner or an accountant who
-- works across the whole company, to someone employed on that day, on or before today:
--   debit   Loans and advances to staff    the amount
--   credit  the cash or bank account       the amount
CREATE FUNCTION app.issue_staff_loan(p_employee uuid, p_date date, p_amount numeric, p_instalment numeric, p_account uuid, p_note text) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_me uuid := app.current_user_id();
  v_id uuid := gen_random_uuid();
  v_name text;
  v_number text;
  v_journal uuid;
BEGIN
  IF v_tenant IS NULL OR v_me IS NULL OR app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'accountant') OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'a loan to staff is paid by the owner or an accountant who works across the whole company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_date IS NULL OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that day has not come yet' USING ERRCODE = 'SE371';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount >= 1e12 OR p_instalment IS NULL OR p_instalment <= 0 OR p_instalment > p_amount THEN
    RAISE EXCEPTION 'a loan has an amount, and an instalment no more than it' USING ERRCODE = 'SE372';
  END IF;
  SELECT e.name INTO v_name FROM public.employees e
    WHERE e.tenant_id = v_tenant AND e.id = p_employee AND e.joined_on <= p_date AND (e.left_on IS NULL OR e.left_on >= p_date) FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'a loan is made to someone employed on that day' USING ERRCODE = 'SE373';
  END IF;
  PERFORM 1 FROM public.accounts a WHERE a.tenant_id = v_tenant AND a.id = p_account AND a.control_type IN ('cash', 'bank') AND NOT a.is_group AND a.archived_at IS NULL FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'a loan is paid from a cash or bank account that is in use' USING ERRCODE = 'SE374';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  v_number := app.next_document_number('SL', p_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, created_by)
    VALUES (v_tenant, p_date, 'staff_loan', v_id, v_number, left('Loan to ' || v_name, 500), v_me) RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, 'staff_advances'), p_amount, 0, left('Loan to ' || v_name, 500)),
           (v_tenant, v_journal, 2, p_account, 0, p_amount, 'Loan ' || v_number);
  INSERT INTO public.staff_loans (id, tenant_id, number, employee_id, issued_on, amount, instalment, account_id, journal_id, note, created_by)
    VALUES (v_id, v_tenant, v_number, p_employee, p_date, p_amount, p_instalment, p_account, v_journal, nullif(left(btrim(p_note), 300), ''), v_me);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_me, app.tenant_role(), 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'staff_loan', 'sourceId', v_id, 'number', v_number, 'lines', 2, 'total', p_amount::text)),
           (v_tenant, v_me, app.tenant_role(), 'staff_loan.issue', 'staff_loan', v_id,
      jsonb_build_object('number', v_number, 'employee', p_employee, 'date', p_date, 'amount', p_amount::text, 'instalment', p_instalment::text, 'account', p_account));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.issue_staff_loan(uuid, date, numeric, numeric, uuid, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.issue_staff_loan(uuid, date, numeric, numeric, uuid, text) TO app_runtime;
--> statement-breakpoint
-- What is still owed on a loan paid back in cash (when someone leaves with more owed than their
-- last pay could cover, or chooses to): LR-2627-00001.
--   debit   the cash or bank account       the amount
--   credit  Loans and advances to staff    the amount
CREATE FUNCTION app.repay_staff_loan(p_loan uuid, p_date date, p_amount numeric, p_account uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_me uuid := app.current_user_id();
  v_loan public.staff_loans%ROWTYPE;
  v_number text;
  v_journal uuid;
  -- Each repayment is its own movement, and its journal stands on that movement (a loan is
  -- repaid as many times as it takes).
  v_movement uuid := gen_random_uuid();
BEGIN
  IF v_tenant IS NULL OR v_me IS NULL OR app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'accountant') OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'a loan is repaid to the owner or an accountant who works across the whole company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Held: an approval taking an instalment meanwhile waits, and then reads what is left.
  SELECT s.* INTO v_loan FROM public.staff_loans s WHERE s.tenant_id = v_tenant AND s.id = p_loan FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such loan in this company' USING ERRCODE = 'SE375';
  END IF;
  IF p_date IS NULL OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date OR p_date < v_loan.issued_on THEN
    RAISE EXCEPTION 'a loan is repaid on or after the day it was made, and not on a day still to come' USING ERRCODE = 'SE371';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > v_loan.amount - v_loan.recovered THEN
    RAISE EXCEPTION 'repay no more than is owed on the loan: %', (v_loan.amount - v_loan.recovered)::text USING ERRCODE = 'SE372';
  END IF;
  PERFORM 1 FROM public.accounts a WHERE a.tenant_id = v_tenant AND a.id = p_account AND a.control_type IN ('cash', 'bank') AND NOT a.is_group AND a.archived_at IS NULL FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'a loan is repaid into a cash or bank account that is in use' USING ERRCODE = 'SE374';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  v_number := app.next_document_number('LR', p_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, created_by)
    VALUES (v_tenant, p_date, 'staff_loan_repayment', v_movement, v_number, 'Repayment of loan ' || v_loan.number, v_me) RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, 1, p_account, p_amount, 0, 'Repayment of loan ' || v_loan.number),
           (v_tenant, v_journal, 2, app.control_account(v_tenant, 'staff_advances'), 0, p_amount, 'Repayment of loan ' || v_loan.number);
  INSERT INTO public.staff_loan_movements (id, tenant_id, loan_id, kind, amount, movement_date, number, account_id, journal_id, created_by)
    VALUES (v_movement, v_tenant, p_loan, 'repaid', p_amount, p_date, v_number, p_account, v_journal, v_me);
  UPDATE public.staff_loans s SET recovered = s.recovered + p_amount WHERE s.tenant_id = v_tenant AND s.id = p_loan;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_me, app.tenant_role(), 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'staff_loan_repayment', 'sourceId', v_movement, 'number', v_number, 'lines', 2, 'total', p_amount::text)),
           (v_tenant, v_me, app.tenant_role(), 'staff_loan.repay', 'staff_loan', p_loan,
      jsonb_build_object('number', v_number, 'loan', v_loan.number, 'date', p_date, 'amount', p_amount::text, 'stillOwed', (v_loan.amount - v_loan.recovered - p_amount)::text));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.repay_staff_loan(uuid, date, numeric, uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.repay_staff_loan(uuid, date, numeric, uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: the shared lists (drizzle/0019_journal_documents.sql) ─────────────────────────
-- A loan's journal and a repayment's stand with them; neither is reversed in this step.
CREATE FUNCTION app.journal_backed_staff_loan(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (SELECT 1 FROM public.staff_loans s WHERE s.tenant_id = p_journal.tenant_id AND s.id = p_journal.source_id AND s.journal_id = p_journal.id
      AND s.number = p_journal.document_number AND s.issued_on = p_journal.journal_date)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.journal_backed_staff_loan_repayment(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (SELECT 1 FROM public.staff_loan_movements m WHERE m.tenant_id = p_journal.tenant_id AND m.id = p_journal.source_id AND m.journal_id = p_journal.id
      AND m.number = p_journal.document_number AND m.movement_date = p_journal.journal_date AND m.kind = 'repaid')
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.journal_backed_staff_loan(public.journals), app.journal_backed_staff_loan_repayment(public.journals) FROM PUBLIC;
